using System.Runtime.InteropServices; using PowerPoint=Microsoft.Office.Interop.PowerPoint; using Office=Microsoft.Office.Core;
namespace PresenterConsole.Desktop;
public sealed class PowerPointAdapter:IPresentationAdapter { readonly PowerPoint.Application app; PowerPoint.Presentation? presentation; public event EventHandler? StateChanged; public int CurrentShowPosition{get;private set;} public int SlideCount=>presentation?.Slides.Count??0; public string CurrentNotes=>ReadNotes(CurrentShowPosition); public PowerPointAdapter(){app=new();app.PresentationOpen+=Open;app.PresentationClose+=Close;foreach(PowerPoint.Presentation p in app.Presentations)Attach(p);} void Open(PowerPoint.Presentation p)=>Attach(p); void Close(PowerPoint.Presentation p){if(ReferenceEquals(p,presentation))presentation=null;StateChanged?.Invoke(this,EventArgs.Empty);} void Attach(PowerPoint.Presentation p){presentation=p;p.SlideShowNextSlide+=NextSlide;StateChanged?.Invoke(this,EventArgs.Empty);} void NextSlide(PowerPoint.SlideShowWindow w){try{CurrentShowPosition=w.View.CurrentShowPosition;StateChanged?.Invoke(this,EventArgs.Empty);}catch(COMException){}}
 public void Next(){try{presentation?.SlideShowWindow?.View.Next();}catch(COMException){}} public void Previous(){try{presentation?.SlideShowWindow?.View.Previous();}catch(COMException){}} public void GotoSlide(int s){try{if(s>0)presentation?.SlideShowWindow?.View.GotoSlide(s);}catch(COMException){}} string ReadNotes(int pos){if(presentation is null||pos<1||pos>SlideCount)return string.Empty;using var t=new COMReferenceTracker();try{var page=t.Track(presentation.Slides[pos].NotesPage);var a=new List<string>();for(int i=1;i<=page.Shapes.Count;i++){var sh=t.Track(page.Shapes[i]);if(sh.HasTextFrame==Office.MsoTriState.msoTrue&&sh.TextFrame.HasText==Office.MsoTriState.msoTrue)a.Add(sh.TextFrame.TextRange.Text);}return string.Join(Environment.NewLine,a);}catch(COMException){return string.Empty;}} public void Dispose(){try{if(presentation is not null)presentation.SlideShowNextSlide-=NextSlide;app.PresentationOpen-=Open;app.PresentationClose-=Close;}catch(COMException){}if(Marshal.IsComObject(presentation))Marshal.FinalReleaseComObject(presentation);if(Marshal.IsComObject(app))Marshal.FinalReleaseComObject(app);}}